<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { createAIGeneration, errorMessage, getAIAgents, getAIAvailability, getAIGenerations, getMaterials, getProjects, saveAIGenerationAsMaterial, type AIAgent, type AIGeneration, type Material, type Project } from '../../api'
import FeedbackBanner from '../../components/FeedbackBanner.vue'
import PageHeader from '../../components/PageHeader.vue'
import { AI_PROPOSAL_ARTIFACTS, PAPER_TYPES, agentMetadata, aiStatusLabel, aiUnavailableMessage, canGenerateAI, isAIDemoMode, paperAgentsForType, shouldPollAI, type AITrack, type PaperType } from '../../stores/aiModel'
import { makeFeedback, type FeedbackState } from '../../stores/feedbackModel'

const route = useRoute(); const track = ref<AITrack>('proposal'); const paperType = ref<PaperType>('empirical'); const workflow = ref('proposal_topic'); const selectedAgentKey = ref('proposal-topic')
const agents = ref<AIAgent[]>([]); const history = ref<AIGeneration[]>([]); const materials = ref<Material[]>([]); const projects = ref<Project[]>([]); const projectId = ref<number | null>(null); const prompt = ref(''); const loading = ref(false); const savingId = ref<number | null>(null); const serviceStatus = ref<string | null>(null); const remainingQuota = ref<number | null>(null); const feedback = ref<FeedbackState | null>(null); const drafts = reactive<Record<number, string>>({}); const saveMaterialIds = reactive<Record<number, number>>({}); let timer: number | undefined
const role = computed(() => route.path.startsWith('/teacher') ? 'teacher' : 'student'); const aiReady = computed(() => canGenerateAI(serviceStatus.value)); const isDemo = computed(() => isAIDemoMode(serviceStatus.value)); const currentPaperAgents = computed(() => paperAgentsForType(paperType.value)); const selectedAgent = computed(() => agents.value.find((agent) => agent.key === selectedAgentKey.value) ?? null); const selectedMetadata = computed(() => selectedAgent.value ? agentMetadata(selectedAgent.value) : currentPaperAgents.value.find((agent) => agent.key === selectedAgentKey.value)); const selectedTitle = computed(() => track.value === 'proposal' ? AI_PROPOSAL_ARTIFACTS.find((item) => item.workflow === workflow.value)?.title ?? '课题申报材料' : selectedMetadata.value?.name ?? '论文写作助手')
function selectProposal(item: typeof AI_PROPOSAL_ARTIFACTS[number]) { track.value = 'proposal'; workflow.value = item.workflow; selectedAgentKey.value = item.agentKey; prompt.value = `请协助完成「${item.title}」。\n\n已知项目事实、数据或想法：\n` }
function selectPaper(agent: ReturnType<typeof paperAgentsForType>[number]) { track.value = 'paper'; workflow.value = agent.workflow; selectedAgentKey.value = agent.key; prompt.value = `论文类型：${PAPER_TYPES.find((item) => item.key === paperType.value)?.label}\n当前环节：${agent.stage}\n\n已有事实、材料或问题：\n` }
function applyQuerySelection() { const q = route.query; const queryWorkflow = typeof q.workflow === 'string' ? q.workflow : ''; const queryAgent = typeof q.agent === 'string' ? q.agent : ''; if (q.track === 'paper' || queryWorkflow.startsWith('paper_')) track.value = 'paper'; if (queryWorkflow) workflow.value = queryWorkflow; if (queryAgent) selectedAgentKey.value = queryAgent; if (typeof q.taskId === 'string') prompt.value = `关联任务 #${q.taskId}\n${prompt.value}` }
async function loadHistory() { history.value = (await getAIGenerations(projectId.value ?? undefined)).data; history.value.filter((item) => item.status === 'completed').forEach((item) => { drafts[item.id] ??= item.artifact_payload?.draft || item.output; saveMaterialIds[item.id] ??= item.material || materials.value.find((material) => material.project === item.project)?.id || 0 }); window.clearTimeout(timer); if (history.value.some((item) => shouldPollAI(item.status))) timer = window.setTimeout(() => loadHistory().catch(() => undefined), 1500) }
async function load() { try { const [projectResponse, availabilityResponse, agentResponse, materialResponse] = await Promise.all([getProjects(), getAIAvailability().catch(() => null), getAIAgents().catch(() => null), getMaterials().catch(() => null)]); projects.value = projectResponse.data; projectId.value = projects.value[0]?.id ?? null; serviceStatus.value = availabilityResponse?.data.status ?? 'unavailable'; remainingQuota.value = availabilityResponse?.data.remaining_quota ?? null; agents.value = agentResponse?.data ?? []; materials.value = materialResponse?.data ?? []; applyQuerySelection(); await loadHistory() } catch (reason) { feedback.value = makeFeedback('error', errorMessage(reason), 'AI 历史没有加载完成，可以刷新重试。', '重试') } }
async function generate() { if (!aiReady.value) { feedback.value = makeFeedback('info', aiUnavailableMessage(serviceStatus.value)); return }; if (!projectId.value) { feedback.value = makeFeedback('error', '请先创建或认领一个项目。'); return }; if (!prompt.value.trim()) { feedback.value = makeFeedback('error', '请补充真实项目事实、材料或要解决的问题。'); return }; loading.value = true; feedback.value = null; try { const task = Number(route.query.taskId) || undefined; await createAIGeneration({ project: projectId.value, agent_key: selectedAgentKey.value, purpose: selectedTitle.value, prompt: prompt.value, context_scope: { project_basics: true, current_task: Boolean(task) }, task, material: task ? materials.value.find((item) => item.task === task)?.id : undefined, paper_type: track.value === 'paper' ? paperType.value : undefined }); await loadHistory(); feedback.value = makeFeedback('success', 'AI 草稿任务已创建。', '请核对事实、数据和引用后，再将草稿保存为项目材料。') } catch (reason) { feedback.value = makeFeedback('error', errorMessage(reason), '没有发送成功，当前输入仍保留。', '重试') } finally { loading.value = false } }
async function saveAsMaterial(item: AIGeneration) { const material = saveMaterialIds[item.id]; if (!material) { feedback.value = makeFeedback('error', '请选择要保存到的项目材料。'); return }; savingId.value = item.id; try { await saveAIGenerationAsMaterial(item.id, { material, content: drafts[item.id], revision_note: 'AI 草稿，经学生编辑后保存' }); await loadHistory(); feedback.value = makeFeedback('success', '已保存为项目材料草稿。', '已保留 AI 来源与核验项；它仍需你核对、补充和按正常流程提交。') } catch (reason) { feedback.value = makeFeedback('error', errorMessage(reason), '保存失败，编辑内容仍在此处。', '重试') } finally { savingId.value = null } }
onMounted(load); onBeforeUnmount(() => window.clearTimeout(timer))
</script>
<template><div class="page ai-center-page"><PageHeader eyebrow="灵思 AI · 研究共创" title="科创共创中心" description="AI 产出是可编辑草稿。请核对事实、数据和引用；它不会自动提交、审核或发布。" /><FeedbackBanner v-model="feedback" @action="load" /><div v-if="isDemo" class="demo-banner"><strong>演示模式：</strong>当前结果仅供演示，不能替代真实研究与人工核验。</div><nav class="track-switch"><button :class="{ active: track === 'proposal' }" @click="track = 'proposal'">课题申报</button><button :class="{ active: track === 'paper' }" @click="track = 'paper'">论文写作</button></nav>
<section v-if="track === 'proposal'" class="artifact-grid"><button v-for="item in AI_PROPOSAL_ARTIFACTS" :key="item.key" class="artifact-card" :class="{ active: workflow === item.workflow }" @click="selectProposal(item)"><span class="eyebrow">申报材料</span><strong>{{ item.title }}</strong><p>{{ item.description }}</p><small>{{ workflow === item.workflow ? '正在编辑' : '开始共创 →' }}</small></button></section><section v-else class="paper-selector"><div class="paper-types"><button v-for="type in PAPER_TYPES" :key="type.key" :class="{ active: paperType === type.key }" @click="paperType = type.key"><strong>{{ type.label }}</strong><small>{{ type.description }}</small></button></div><div class="agent-grid"><button v-for="agent in currentPaperAgents" :key="agent.key" :class="{ active: selectedAgentKey === agent.key }" @click="selectPaper(agent)"><span>{{ agent.stage }}</span><strong>{{ agent.name }}</strong><small>{{ agent.quickActions.join(' · ') }}</small></button></div></section>
<section class="workbench paper-card"><header><div><span class="eyebrow">当前共创</span><h2>{{ selectedTitle }}</h2></div><small v-if="selectedMetadata">{{ selectedMetadata.workflow }} · {{ selectedMetadata.stage }}</small></header><label>提供真实项目上下文<textarea v-model="prompt" :disabled="!aiReady" rows="6" placeholder="研究对象、已有观察、数据来源、限制条件和你真正不确定的问题……" /></label><footer><span>{{ aiReady ? '生成后请完成核验，再保存为材料。' : aiUnavailableMessage(serviceStatus) }}</span><button class="primary-button" :disabled="loading || !aiReady" @click="generate">{{ loading ? '正在创建…' : '生成结构化草稿' }}</button></footer><p v-if="remainingQuota !== null" class="form-hint">本校本月剩余 {{ remainingQuota }} 次 AI 调用配额。</p></section>
<section class="history-section"><div class="history-heading"><div><span class="eyebrow">生成记录</span><h2>草稿、核验与下一步</h2></div><button class="secondary-button" @click="load">刷新</button></div><p v-if="!history.length" class="history-empty">尚无生成记录。选择一个材料或论文智能体开始共创。</p><article v-for="item in history" :key="item.id" class="generation-card" :class="item.status"><header><div><strong>{{ item.artifact_payload?.title || item.purpose }}</strong><small>{{ item.created_at.slice(0, 16).replace('T', ' ') }} · {{ item.model_name || item.actor_name }}</small></div><span>{{ aiStatusLabel(item.status) }}</span></header><p v-if="item.status === 'failed'" class="form-error">{{ item.error_message || '生成失败' }}</p><p v-else-if="item.status !== 'completed'" class="form-hint">{{ aiStatusLabel(item.status) }}，完成后会自动刷新。</p><template v-else><label>可编辑草稿<textarea v-model="drafts[item.id]" rows="8" /></label><div class="verification"><strong>核验清单</strong><ul><li v-for="check in item.verification_items?.length ? item.verification_items : ['核对全部事实、数据和引用来源。']" :key="check">{{ check }}</li></ul></div><p class="next-action"><strong>下一步：</strong>{{ item.artifact_payload?.next_action || '结合真实项目补充证据，再按材料流程提交。' }}</p><footer><select v-model.number="saveMaterialIds[item.id]" aria-label="选择项目材料"><option :value="0">选择项目材料</option><option v-for="material in materials.filter((entry) => entry.project === item.project)" :key="material.id" :value="material.id">{{ material.title }}</option></select><small v-if="item.saved_material_revision">已保存为材料版本 #{{ item.saved_material_revision }}</small><button class="secondary-button" :disabled="savingId === item.id || Boolean(item.saved_material_revision)" @click="saveAsMaterial(item)">{{ item.saved_material_revision ? '已保存为材料' : savingId === item.id ? '正在保存…' : '保存为项目材料' }}</button></footer></template></article></section></div></template>
<style scoped>
.demo-banner,.workbench,.generation-card{margin-bottom:16px;padding:16px;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--paper)}.demo-banner{background:var(--sage-soft);color:var(--moss-dark)}.track-switch{display:flex;gap:8px;margin-bottom:16px}.track-switch button,.paper-types button,.agent-grid button,.artifact-card{border:1px solid var(--line);background:var(--paper);border-radius:var(--radius-md);color:var(--ink);cursor:pointer}.track-switch button{padding:10px 20px;font-weight:700}.track-switch .active,.paper-types .active,.agent-grid .active,.artifact-card.active{border-color:var(--moss);background:var(--sage-soft);color:var(--moss-dark)}.artifact-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:16px}.artifact-card{text-align:left;padding:16px;min-height:142px}.artifact-card strong,.artifact-card small{display:block}.artifact-card strong{margin:8px 0}.artifact-card p,.artifact-card small,.paper-types small,.agent-grid small{font-size:12px;color:var(--muted);line-height:1.6}.paper-selector{margin-bottom:16px}.paper-types,.agent-grid{display:grid;gap:10px}.paper-types{grid-template-columns:repeat(4,1fr);margin-bottom:10px}.paper-types button,.agent-grid button{padding:13px;text-align:left}.paper-types strong,.paper-types small,.agent-grid strong,.agent-grid small,.agent-grid span{display:block}.agent-grid{grid-template-columns:repeat(6,1fr)}.agent-grid span{font-size:11px;color:var(--moss);margin-bottom:4px}.agent-grid strong{font-size:13px;margin-bottom:5px}.workbench header,.history-heading,.generation-card header,.workbench footer,.generation-card footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.workbench h2,.history-heading h2{font-family:var(--serif);font-size:20px;margin:3px 0 14px}.workbench label,.generation-card label{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--muted)}textarea{width:100%;box-sizing:border-box;border:1px solid var(--line-dark);border-radius:var(--radius-sm);padding:10px;font:inherit;color:var(--ink);resize:vertical;background:var(--paper)}textarea:focus{outline:none;border-color:var(--moss);box-shadow:0 0 0 3px rgba(73,110,69,.12)}.workbench footer{margin-top:12px;font-size:12px;color:var(--muted)}.primary-button,.secondary-button{border-radius:var(--radius-sm);padding:8px 14px;font-size:13px;cursor:pointer}.primary-button{border:1px solid var(--moss-dark);background:var(--moss);color:#fff}.secondary-button{border:1px solid var(--line-dark);background:var(--paper);color:var(--moss-dark)}button:disabled{opacity:.55;cursor:not-allowed}.form-hint{font-size:12px;color:var(--muted)}.history-section{margin-top:24px}.history-empty{padding:24px;border:1px dashed var(--line-dark);border-radius:var(--radius-md);color:var(--muted);text-align:center}.generation-card header{margin-bottom:12px}.generation-card header small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.generation-card header>span{font-size:12px;color:var(--moss-dark);background:var(--sage-soft);padding:4px 8px;border-radius:999px}.generation-card.failed header>span{color:var(--clay)}.verification{margin-top:12px;padding:10px 12px;background:var(--paper-soft);border-radius:var(--radius-sm);font-size:13px}.verification ul{margin:6px 0 0;padding-left:18px}.verification li{margin:3px 0}.next-action{font-size:13px;line-height:1.6}.generation-card footer{margin-top:12px}.generation-card footer small{color:var(--muted)}.form-error{color:#b33;font-size:13px}@media(max-width:1000px){.artifact-grid{grid-template-columns:repeat(2,1fr)}.paper-types{grid-template-columns:repeat(2,1fr)}.agent-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.artifact-grid,.paper-types,.agent-grid{grid-template-columns:1fr}.workbench header,.history-heading,.generation-card header,.workbench footer,.generation-card footer{align-items:flex-start;flex-direction:column}}
</style>
